File: force-app/main/default/classes/RecordSearchService.cls

```apex
/**
 * Service used by the admin "record finder" Lightning component to run simple
 * equality-filter searches against any object.
 *
 * Security notes:
 *  - The class is declared `with sharing` and the query is executed in USER_MODE
 *    so record sharing and field-level security are enforced for the running user.
 *  - All object / field names are validated against the schema (case-insensitively)
 *    and the canonical API names are used when building the SOQL string, so no
 *    user-supplied text is concatenated into the query.
 *  - Filter values are passed as bind variables, preventing SOQL injection.
 */
public with sharing class RecordSearchService {

    /** The only exception type this service throws. */
    public class SearchException extends Exception {}

    public static List<SObject> search(
        String objectApiName,
        List<String> fields,
        Map<String, Object> filters,
        String orderByField,
        Integer maxRows
    ) {
        // ---- Basic argument validation -------------------------------------
        if (maxRows == null || maxRows < 1 || maxRows > 200) {
            throw new SearchException('maxRows must be between 1 and 200.');
        }
        if (fields == null || fields.isEmpty()) {
            throw new SearchException('At least one field must be specified.');
        }
        if (String.isBlank(objectApiName)) {
            throw new SearchException('Object API name is required.');
        }

        // ---- Resolve and validate the object -------------------------------
        Schema.DescribeSObjectResult objDescribe = getObjectDescribe(objectApiName);
        if (objDescribe == null) {
            throw new SearchException('Object does not exist: ' + objectApiName);
        }
        if (!objDescribe.isAccessible()) {
            throw new SearchException('You do not have read access to object: ' + objDescribe.getName());
        }

        Map<String, Schema.SObjectField> fieldMap = objDescribe.fields.getMap();

        // ---- SELECT clause -------------------------------------------------
        Set<String> alreadySelected = new Set<String>{ 'id' };
        List<String> selectFields = new List<String>{ 'Id' };

        for (String f : fields) {
            if (String.isBlank(f)) {
                throw new SearchException('Field name cannot be blank.');
            }
            Schema.DescribeFieldResult dfr = describeField(fieldMap, f);
            if (dfr == null) {
                throw new SearchException('Unknown field: ' + f);
            }
            if (!dfr.isAccessible()) {
                throw new SearchException('You do not have read access to field: ' + dfr.getName());
            }
            String apiName = dfr.getName();
            if (!alreadySelected.contains(apiName.toLowerCase())) {
                selectFields.add(apiName);
                alreadySelected.add(apiName.toLowerCase());
            }
        }

        String query = 'SELECT ' + String.join(selectFields, ', ')
                     + ' FROM ' + objDescribe.getName();

        // ---- WHERE clause --------------------------------------------------
        Map<String, Object> binds = new Map<String, Object>();

        if (filters != null && !filters.isEmpty()) {
            List<String> conditions = new List<String>();
            Integer idx = 0;

            for (String key : filters.keySet()) {
                if (String.isBlank(key)) {
                    throw new SearchException('Filter field name cannot be blank.');
                }
                Schema.DescribeFieldResult dfr = describeField(fieldMap, key);
                if (dfr == null) {
                    throw new SearchException('Unknown filter field: ' + key);
                }
                if (!dfr.isAccessible()) {
                    throw new SearchException('You do not have read access to filter field: ' + dfr.getName());
                }
                if (!dfr.isFilterable()) {
                    throw new SearchException('Field cannot be filtered: ' + dfr.getName());
                }

                String bindName = 'bind' + idx;
                conditions.add(dfr.getName() + ' = :' + bindName);
                binds.put(bindName, filters.get(key));
                idx++;
            }

            query += ' WHERE ' + String.join(conditions, ' AND ');
        }

        // ---- ORDER BY clause -----------------------------------------------
        if (String.isNotBlank(orderByField)) {
            Schema.DescribeFieldResult dfr = describeField(fieldMap, orderByField);
            if (dfr == null) {
                throw new SearchException('Unknown order by field: ' + orderByField);
            }
            if (!dfr.isAccessible()) {
                throw new SearchException('You do not have read access to order by field: ' + dfr.getName());
            }
            if (!dfr.isSortable()) {
                throw new SearchException('Field cannot be sorted: ' + dfr.getName());
            }
            query += ' ORDER BY ' + dfr.getName() + ' ASC';
        }

        // ---- LIMIT ---------------------------------------------------------
        query += ' LIMIT :maxRowsBind';
        binds.put('maxRowsBind', maxRows);

        // ---- Execute -------------------------------------------------------
        try {
            return Database.queryWithBinds(query, binds, AccessLevel.USER_MODE);
        } catch (Exception e) {
            // Never leak a non-SearchException to the caller.
            throw new SearchException(e.getMessage());
        }
    }

    // -----------------------------------------------------------------------
    // Helpers
    // -----------------------------------------------------------------------

    private static Schema.DescribeSObjectResult getObjectDescribe(String objectApiName) {
        Schema.SObjectType sot = Schema.getGlobalDescribe().get(objectApiName.toLowerCase());
        return (sot == null) ? null : sot.getDescribe();
    }

    private static Schema.DescribeFieldResult describeField(
        Map<String, Schema.SObjectField> fieldMap,
        String fieldName
    ) {
        Schema.SObjectField token = fieldMap.get(fieldName.toLowerCase());
        return (token == null) ? null : token.getDescribe();
    }
}
