/**
 * Parses e-commerce order payloads posted as JSON to an Apex REST endpoint.
 */
public class OrderPayloadParser {

    /**
     * Custom exception thrown for any invalid payload condition.
     */
    public class PayloadException extends Exception {}

    /**
     * Represents a single order line.
     */
    public class Line {
        public String sku;
        public Integer quantity;
        public Decimal unitPrice;
        public Decimal discount;
        public Decimal lineTotal;
    }

    /**
     * Represents a parsed order.
     */
    public class Order {
        public String orderNumber;
        public Date orderDate;
        public String currencyCode;
        public String customerEmail;
        public List<Line> lines;
        public Decimal total;
    }

    /**
     * Parse a raw JSON body into an Order.
     */
    public static Order parse(String body) {
        if (String.isBlank(body)) {
            throw new PayloadException('Body is null or blank.');
        }

        Object parsed;
        try {
            parsed = JSON.deserializeUntyped(body);
        } catch (Exception e) {
            throw new PayloadException('Body is not valid JSON.');
        }

        if (!(parsed instanceof Map<String, Object>)) {
            throw new PayloadException('Body is not a JSON object.');
        }

        Map<String, Object> root = (Map<String, Object>) parsed;

        Order order = new Order();

        // number (required, non-blank)
        Object numberObj = root.get('number');
        String number = (numberObj == null) ? null : String.valueOf(numberObj);
        if (String.isBlank(number)) {
            throw new PayloadException('Missing or blank "number".');
        }
        order.orderNumber = number;

        // date (optional, ISO yyyy-MM-dd)
        Object dateObj = root.get('date');
        if (dateObj != null) {
            String ds = String.valueOf(dateObj);
            if (!String.isBlank(ds)) {
                try {
                    order.orderDate = Date.valueOf(ds);
                } catch (Exception e) {
                    throw new PayloadException('Invalid "date" value: ' + ds);
                }
            }
        }

        // currency (optional)
        Object currencyObj = root.get('currency');
        order.currencyCode = (currencyObj == null) ? null : String.valueOf(currencyObj);

        // customer.email (optional)
        Object customerObj = root.get('customer');
        if (customerObj != null) {
            if (!(customerObj instanceof Map<String, Object>)) {
                throw new PayloadException('"customer" is not a JSON object.');
            }
            Map<String, Object> customer = (Map<String, Object>) customerObj;
            Object emailObj = customer.get('email');
            order.customerEmail = (emailObj == null) ? null : String.valueOf(emailObj);
        }

        // lines (optional; empty when missing or null)
        List<Line> lineList = new List<Line>();
        Decimal total = 0;

        Object linesObj = root.get('lines');
        if (linesObj != null) {
            if (!(linesObj instanceof List<Object>)) {
                throw new PayloadException('"lines" is not a JSON array.');
            }
            List<Object> rawLines = (List<Object>) linesObj;
            for (Object lineObj : rawLines) {
                if (!(lineObj instanceof Map<String, Object>)) {
                    throw new PayloadException('A line is not a JSON object.');
                }
                Map<String, Object> lm = (Map<String, Object>) lineObj;

                Line line = new Line();

                // sku (required)
                Object skuObj = lm.get('sku');
                if (skuObj == null) {
                    throw new PayloadException('A line is missing "sku".');
                }
                line.sku = String.valueOf(skuObj);

                // quantity (required, positive)
                Decimal qty = toDecimal(lm.get('quantity'));
                if (qty == null || qty <= 0) {
                    throw new PayloadException('A line has a missing or non-positive "quantity".');
                }
                line.quantity = qty.intValue();

                // unitPrice (required, non-negative)
                Decimal unitPrice = toDecimal(lm.get('unitPrice'));
                if (unitPrice == null || unitPrice < 0) {
                    throw new PayloadException('A line has a missing or negative "unitPrice".');
                }
                line.unitPrice = unitPrice;

                // discount (optional; default 0)
                Decimal discount = toDecimal(lm.get('discount'));
                if (discount == null) {
                    discount = 0;
                }
                line.discount = discount;

                // lineTotal = quantity x unitPrice x (1 - discount), 2 dp HALF_UP
                Decimal lineTotal = (Decimal.valueOf(line.quantity) * unitPrice * (1 - discount))
                    .setScale(2, System.RoundingMode.HALF_UP);
                line.lineTotal = lineTotal;

                total += lineTotal;

                lineList.add(line);
            }
        }

        order.lines = lineList;
        order.total = total;

        return order;
    }

    /**
     * Build an acknowledgement JSON object with exactly four keys:
     * number, status, lineCount, total.
     */
    public static String toAcknowledgement(Order order) {
        Integer lineCount = (order == null || order.lines == null) ? 0 : order.lines.size();
        Decimal total = (order == null || order.total == null) ? 0 : order.total;
        String number = (order == null) ? null : order.orderNumber;

        JSONGenerator gen = JSON.createGenerator(false);
        gen.writeStartObject();
        gen.writeStringField('number', number);
        gen.writeStringField('status', 'RECEIVED');
        gen.writeNumberField('lineCount', lineCount);
        gen.writeNumberField('total', total);
        gen.writeEndObject();
        return gen.getAsString();
    }

    /**
     * Safely convert a deserialized JSON value to a Decimal, avoiding
     * binary floating-point precision issues by routing through String.
     */
    private static Decimal toDecimal(Object o) {
        if (o == null) {
            return null;
        }
        if (o instanceof Decimal) {
            return (Decimal) o;
        }
        if (o instanceof Integer) {
            return Decimal.valueOf((Integer) o);
        }
        if (o instanceof Long) {
            return Decimal.valueOf((Long) o);
        }
        try {
            return Decimal.valueOf(String.valueOf(o));
        } catch (Exception e) {
            return null;
        }
    }
}
