public with sharing class PicklistService {

    /**
     * Represents a single active picklist entry.
     */
    public class Option {
        public String value;
        public String label;
        public Boolean isDefault;

        public Option(String value, String label, Boolean isDefault) {
            this.value = value;
            this.label = label;
            this.isDefault = isDefault;
        }
    }

    /**
     * Custom exception thrown for any invalid input or lookup failure.
     */
    public class PicklistServiceException extends Exception {}

    /**
     * Returns the active values of the given picklist / multi-select picklist field,
     * in the order they are defined on the field.
     */
    public static List<PicklistService.Option> activeOptions(String objectApiName, String fieldApiName) {

        if (String.isBlank(objectApiName)) {
            throw new PicklistServiceException('Object API name must not be null or blank.');
        }
        if (String.isBlank(fieldApiName)) {
            throw new PicklistServiceException('Field API name must not be null or blank.');
        }

        // Resolve the object (case-insensitive). getGlobalDescribe keys are lowercase.
        Schema.SObjectType sObjType = Schema.getGlobalDescribe().get(objectApiName.toLowerCase());
        if (sObjType == null) {
            throw new PicklistServiceException('Object does not exist: ' + objectApiName);
        }

        // Resolve the field (case-insensitive). fields map keys are lowercase.
        Schema.DescribeSObjectResult objDescribe = sObjType.getDescribe();
        Schema.SObjectField fieldToken = objDescribe.fields.getMap().get(fieldApiName.toLowerCase());
        if (fieldToken == null) {
            throw new PicklistServiceException(
                'Field does not exist on ' + objDescribe.getName() + ': ' + fieldApiName
            );
        }

        Schema.DescribeFieldResult fieldDescribe = fieldToken.getDescribe();
        Schema.DisplayType fieldType = fieldDescribe.getType();
        if (fieldType != Schema.DisplayType.PICKLIST && fieldType != Schema.DisplayType.MULTIPICKLIST) {
            throw new PicklistServiceException(
                'Field is not a picklist or multi-select picklist: ' + fieldDescribe.getName()
            );
        }

        // getPicklistValues() only returns active entries, in definition order.
        List<PicklistService.Option> options = new List<PicklistService.Option>();
        for (Schema.PicklistEntry entry : fieldDescribe.getPicklistValues()) {
            if (entry.isActive()) {
                options.add(new PicklistService.Option(
                    entry.getValue(),
                    entry.getLabel(),
                    entry.isDefaultValue()
                ));
            }
        }

        return options;
    }
}
