public with sharing class OpportunityPipelineHandler {

    public static void handleAfterInsert(List<Opportunity> newList) {
        recalculate(collectAccountIds(newList, null));
    }

    public static void handleAfterUpdate(List<Opportunity> newList, Map<Id, Opportunity> oldMap) {
        // Include both old and new account ids so that reparenting updates both accounts.
        recalculate(collectAccountIds(newList, oldMap.values()));
    }

    public static void handleAfterDelete(List<Opportunity> oldList) {
        recalculate(collectAccountIds(oldList, null));
    }

    public static void handleAfterUndelete(List<Opportunity> newList) {
        recalculate(collectAccountIds(newList, null));
    }

    private static Set<Id> collectAccountIds(List<Opportunity> listA, List<Opportunity> listB) {
        Set<Id> acctIds = new Set<Id>();
        if (listA != null) {
            for (Opportunity o : listA) {
                if (o.AccountId != null) {
                    acctIds.add(o.AccountId);
                }
            }
        }
        if (listB != null) {
            for (Opportunity o : listB) {
                if (o.AccountId != null) {
                    acctIds.add(o.AccountId);
                }
            }
        }
        return acctIds;
    }

    /**
     * Recomputes FB_Open_Pipeline__c and FB_Open_Opportunities__c from scratch for the
     * given accounts and writes only the ones whose totals actually changed.
     *
     * Writing only changed accounts keeps this idempotent, so when the legacy AccountTrigger
     * re-updates open opportunities (which re-fires this trigger), the recomputed values match
     * what is already stored and no further DML is issued - breaking the recursion cycle while
     * remaining correct after every DML statement in the transaction.
     */
    private static void recalculate(Set<Id> acctIds) {
        acctIds.remove(null);
        if (acctIds.isEmpty()) {
            return;
        }

        // Seed every affected account with zeroes so an account whose last open
        // opportunity went away shows 0/0 rather than blank.
        Map<Id, Decimal> pipelineByAcct = new Map<Id, Decimal>();
        Map<Id, Integer> countByAcct = new Map<Id, Integer>();
        for (Id aId : acctIds) {
            pipelineByAcct.put(aId, 0);
            countByAcct.put(aId, 0);
        }

        for (AggregateResult ar : [
            SELECT AccountId aid, COUNT(Id) cnt, SUM(Amount) total
            FROM Opportunity
            WHERE AccountId IN :acctIds AND IsClosed = false
            GROUP BY AccountId
        ]) {
            Id aId = (Id) ar.get('aid');
            Decimal total = (Decimal) ar.get('total'); // SUM ignores null amounts (blank = 0)
            Integer cnt = (Integer) ar.get('cnt');
            pipelineByAcct.put(aId, total == null ? 0 : total);
            countByAcct.put(aId, cnt == null ? 0 : cnt);
        }

        List<Account> toUpdate = new List<Account>();
        for (Account acc : [
            SELECT Id, FB_Open_Pipeline__c, FB_Open_Opportunities__c
            FROM Account
            WHERE Id IN :acctIds
        ]) {
            Decimal newPipeline = pipelineByAcct.get(acc.Id);
            Decimal newCount = countByAcct.get(acc.Id);

            Boolean changed =
                acc.FB_Open_Pipeline__c != newPipeline ||
                acc.FB_Open_Opportunities__c != newCount;

            if (changed) {
                acc.FB_Open_Pipeline__c = newPipeline;
                acc.FB_Open_Opportunities__c = newCount;
                toUpdate.add(acc);
            }
        }

        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
    }
}
