/**
 * Schedulable job that purges old FB_Integration_Log__c records.
 *
 * Retention rules:
 *   - Non-ERROR logs (including blank Level__c) are deleted once they are
 *     older than 30 days.
 *   - ERROR logs are kept longer and deleted only once they are older
 *     than 180 days.
 *
 * Implemented as a Batchable as well so that very large volumes of logs can
 * be purged safely without hitting per-transaction governor limits.
 */
public with sharing class LogPurgeJob implements Schedulable, Database.Batchable<SObject> {

    // No-argument constructor (required for scheduling).
    public LogPurgeJob() {}

    /**
     * Schedulable entry point. Kicks off the batch that performs the delete.
     */
    public void execute(SchedulableContext sc) {
        Database.executeBatch(this, 200);
    }

    /**
     * Batch start: select the records eligible for deletion.
     *
     * A record is eligible when it was created more than 30 days ago AND,
     * if it is an ERROR log, more than 180 days ago.
     *
     * Note: in SOQL, "Level__c != 'ERROR'" also matches rows where Level__c
     * is null/blank, so blank logs are purged after 30 days as required.
     */
    public Database.QueryLocator start(Database.BatchableContext bc) {
        return Database.getQueryLocator(
            'SELECT Id ' +
            'FROM FB_Integration_Log__c ' +
            'WHERE CreatedDate < LAST_N_DAYS:30 ' +
            'AND (Level__c != \'ERROR\' OR CreatedDate < LAST_N_DAYS:180)'
        );
    }

    /**
     * Batch execute: delete the eligible records in bulk.
     */
    public void execute(Database.BatchableContext bc, List<FB_Integration_Log__c> scope) {
        if (!scope.isEmpty()) {
            delete scope;
        }
    }

    /**
     * Batch finish: nothing further to do.
     */
    public void finish(Database.BatchableContext bc) {
        // No post-processing required.
    }

    /**
     * Schedules this job to run every night at 02:00.
     *
     * @return the Id returned by System.schedule.
     */
    public static Id scheduleNightly() {
        // Seconds Minutes Hours Day-of-month Month Day-of-week
        String cron = '0 0 2 * * ?';
        return System.schedule('Log purge (nightly)', cron, new LogPurgeJob());
    }
}
