        ((fflib_ISObjectUnitOfWork) mocks.verify(uow, 0)).registerDirty(opp2);
        ((fflib_ISObjectUnitOfWork) mocks.verify(uow, 0)).registerDirty(opp3);
        ((fflib_ISObjectUnitOfWork) mocks.verify(uow, 0)).registerDirty(opp4);

        // Committed exactly once.
        ((fflib_ISObjectUnitOfWork) mocks.verify(uow, 1)).commitWork();
    }
