public inherited sharing class Accounts extends fflib_SObjects implements IAccounts {
    /**
     * Build a domain instance from an in-memory list of records, through the
     * Application domain factory (so unit tests can replace it via setMock).
     */
    public static IAccounts newInstance(List<Account> records) {
        return (IAccounts) Application.Domain.newInstance(records);
    }

    /**
     * Build a domain instance from a set of Ids. The records are loaded through
     * the domain factory's configured selector.
     */
    public static IAccounts newInstance(Set<Id> accountIds) {
        return (IAccounts) Application.Domain.newInstance(accountIds);
    }

    public Accounts(List<SObject> records) {
        super(records, Schema.Account.SObjectType);
    }

    public Schema.SObjectType getSObjectType() {
        return Schema.Account.SObjectType;
    }

    public List<Account> getAccounts() {
        return (List<Account>) getRecords();
    }

    public IAccounts selectByRating(String rating) {
        List<Account> matched = new List<Account>();
        for (Account record : (List<Account>) getRecords()) {
            if (record.Rating == rating) {
                matched.add(record);
            }
        }
        return Accounts.newInstance(matched);
    }

    public Set<Id> getOwnerIds() {
        Set<Id> ownerIds = new Set<Id>();
        for (Account record : (List<Account>) getRecords()) {
            if (record.OwnerId != null) {
                ownerIds.add(record.OwnerId);
            }
        }
        return ownerIds;
    }

    public void setRating(String rating) {
        for (Account record : (List<Account>) getRecords()) {
            record.Rating = rating;
        }
    }

    /**
     * Used by the Application.Domain factory to construct Accounts instances.
     */
    public class Constructor implements fflib_IDomainConstructor {
        public fflib_SObjects construct(List<Object> objectList) {
            return new Accounts((List<SObject>) objectList);
