    public List<Opportunity> selectTopOpenByAccountIds(Set<Id> accountIds, Integer maxRecords) {
        // Build from the query factory but without the default selection criteria
        // (i.e. without the selector's default "order by Name"), so we can apply
        // our own ordering while keeping the standard field list and security settings.
        fflib_QueryFactory query = newQueryFactory(false);

        // Parent account's Name
        query.selectField('Account.Name');

        query.setCondition('AccountId IN :accountIds AND IsClosed = false');

        // Highest Amount first, opportunities without an Amount last.
        query.addOrdering(
            Opportunity.Amount,
            fflib_QueryFactory.SortOrder.DESCENDING,
            true
        );
        // Equal amounts ordered by earliest CloseDate first.
        query.addOrdering(
            Opportunity.CloseDate,
            fflib_QueryFactory.SortOrder.ASCENDING
        );

        query.setLimit(maxRecords);

        return (List<Opportunity>) Database.query(query.toSOQL());
    }
}
