```apex
public with sharing class AccountOnboardingService {
    /**
     * Creates one Account per map key and one Contact per last name in the
     * entry's list, linking each Contact to its parent Account. All work is
     * performed through a single Unit of Work committed once.
     *
     * @param contactLastNamesByAccountName map of Account name -> list of Contact last names
     * @return the newly created Accounts with their Ids populated
     */
    public static List<Account> createAccountsWithContacts(
        Map<String, List<String>> contactLastNamesByAccountName
    ) {
        List<Account> newAccounts = new List<Account>();

        // Null/empty input: do nothing, return empty list.
        if (contactLastNamesByAccountName == null || contactLastNamesByAccountName.isEmpty()) {
            return newAccounts;
        }

        // Declare SObject types in dependency order (parents before children).
        fflib_SObjectUnitOfWork uow = new fflib_SObjectUnitOfWork(
            new List<Schema.SObjectType>{
                Account.SObjectType,
                Contact.SObjectType
            }
        );

        for (String accountName : contactLastNamesByAccountName.keySet()) {
            Account acct = new Account(Name = accountName);
            uow.registerNew(acct);
            newAccounts.add(acct);

            List<String> lastNames = contactLastNamesByAccountName.get(accountName);
            if (lastNames != null) {
                for (String lastName : lastNames) {
                    Contact con = new Contact(LastName = lastName);
                    // Register child, letting the UoW resolve the AccountId relationship
                    // once the parent Account has been inserted.
                    uow.registerNew(con, Contact.AccountId, acct);
                }
            }
        }

        uow.commitWork();

        return newAccounts;
    }
}
