public with sharing class OpportunityWinService {
    public static Integer markWon(Set<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return 0;
        }

        List<Opportunity> opportunities =
            OpportunitiesSelector.newInstance().selectById(opportunityIds);

        fflib_ISObjectUnitOfWork uow = Application.UnitOfWork.newInstance();

        Date closeDate = Date.today();
        Integer closedCount = 0;

        for (Opportunity opp : opportunities) {
            if (opp.StageName == 'Closed Won') {
                continue;
            }

            opp.StageName = 'Closed Won';
            opp.CloseDate = closeDate;
            uow.registerDirty(opp);

            // Publish only after the opportunity updates commit successfully.
            uow.registerPublishAfterSuccessTransaction(
                new Deal_Won__e(
                    Opportunity_Id__c = opp.Id,
                    Amount__c = opp.Amount
                )
            );

            closedCount++;
        }

        // Single commit: DML runs first, events publish only on success,
        // any failure throws before any Deal_Won__e is published.
        uow.commitWork();

        return closedCount;
    }
}
