public with sharing class FollowUpTaskService {
    /**
     * Creates a follow-up Task for each supplied Opportunity.
     *
     * @param opportunityIds the Opportunities coming out of the pipeline review
     * @return the Ids of the Opportunities whose Task could NOT be created
     *         (empty when every Task was inserted successfully)
     */
    public static Set<Id> createFollowUps(List<Id> opportunityIds) {
        Set<Id> failedOppIds = new Set<Id>();

        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return failedOppIds;
        }

        // Pull the data we need for the tasks in a single query (bulk-safe).
        Map<Id, Opportunity> oppsById = new Map<Id, Opportunity>(
            [
                SELECT Id, Name, OwnerId
                FROM Opportunity
                WHERE Id IN :opportunityIds
            ]
        );

        Date dueDate = Date.today().addDays(7);

        // Build one Task per Opportunity, keeping the Opportunity Id alongside
        // each Task so we can map a failed save result back to its Opportunity.
        List<Task> tasks = new List<Task>();
        List<Id> taskOppIds = new List<Id>();

        for (Id oppId : opportunityIds) {
            Opportunity opp = oppsById.get(oppId);
            if (opp == null) {
                // Id passed in that doesn't resolve to an Opportunity we can read.
                failedOppIds.add(oppId);
                continue;
            }

            tasks.add(new Task(
                WhatId       = opp.Id,
                OwnerId      = opp.OwnerId,
                Subject      = 'Follow up: ' + opp.Name,
                ActivityDate = dueDate,
                Status       = 'Not Started',
                Priority     = 'Normal'
            ));
            taskOppIds.add(opp.Id);
        }

        if (!tasks.isEmpty()) {
            // Partial-success insert: one DML statement, each row's validation-rule
            // failure is reported independently without rolling back the others.
            Database.SaveResult[] results = Database.insert(tasks, false);

            for (Integer i = 0; i < results.size(); i++) {
                if (!results[i].isSuccess()) {
                    failedOppIds.add(taskOppIds[i]);
                }
            }
        }

        return failedOppIds;
    }
}
