trigger OpportunityTrigger on Opportunity (after insert, after update) {
    // Collect the distinct accounts whose rating might be affected by this batch.
    Set<Id> accountIds = new Set<Id>();

    for (Opportunity opp : Trigger.new) {
        if (Trigger.isInsert) {
            if (opp.AccountId != null) {
                accountIds.add(opp.AccountId);
            }
        } else { // update
            Opportunity oldOpp = Trigger.oldMap.get(opp.Id);
            Boolean stageChanged  = opp.StageName != oldOpp.StageName;
            Boolean amountChanged = opp.Amount != oldOpp.Amount;
            Boolean acctChanged   = opp.AccountId != oldOpp.AccountId;

            if (stageChanged || amountChanged || acctChanged) {
                if (opp.AccountId != null) {
                    accountIds.add(opp.AccountId);
                }
                // If the opportunity was reparented, the old account needs recalc too.
                if (acctChanged && oldOpp.AccountId != null) {
                    accountIds.add(oldOpp.AccountId);
                }
            }
        }
    }

    if (!accountIds.isEmpty()) {
        // One async job for the whole batch (see note on @future limits).
        AccountRatingService.recalculate(accountIds);
    }
}
