```apex
public with sharing class AccountRatingService {

    private static final Decimal HOT_THRESHOLD = 100000;

    /**
     * Recalculates the Rating for the given accounts based on their open pipeline:
     *   Hot  - has an open opportunity with Amount >= 100,000
     *   Warm - has open opportunities but none that big
     *   Cold - has no open opportunities
     *
     * Takes a Set<Id> and runs once per transaction to stay well within the
     * 50 @future-calls-per-transaction governor limit for bulk (200+) batches.
     */
    @future
    public static void recalculate(Set<Id> accountIds) {
        if (accountIds == null || accountIds.isEmpty()) {
            return;
        }

        // Default every account to Cold (no open opps).
        Map<Id, String> ratingByAccount = new Map<Id, String>();
        for (Id accId : accountIds) {
            ratingByAccount.put(accId, 'Cold');
        }

        // Aggregate open opportunities per account.
        for (AggregateResult ar : [
            SELECT AccountId acc, MAX(Amount) maxAmount
            FROM Opportunity
            WHERE AccountId IN :accountIds
              AND IsClosed = false
            GROUP BY AccountId
        ]) {
            Id accId = (Id) ar.get('acc');
            Decimal maxAmount = (Decimal) ar.get('maxAmount');

            if (maxAmount != null && maxAmount >= HOT_THRESHOLD) {
                ratingByAccount.put(accId, 'Hot');
            } else {
                // Has open opportunities, but none large (or amount is null).
                ratingByAccount.put(accId, 'Warm');
            }
        }

        // Only update accounts whose Rating actually changes.
        Map<Id, Account> existing = new Map<Id, Account>([
            SELECT Id, Rating
            FROM Account
            WHERE Id IN :accountIds
        ]);

        List<Account> toUpdate = new List<Account>();
        for (Id accId : ratingByAccount.keySet()) {
            Account acc = existing.get(accId);
            if (acc == null) {
                continue; // Account deleted since the trigger fired.
            }
            String newRating = ratingByAccount.get(accId);
            if (acc.Rating != newRating) {
                toUpdate.add(new Account(Id = accId, Rating = newRating));
            }
        }

        if (!toUpdate.isEmpty()) {
            update toUpdate;
        }
    }
}
```

