```apex
public with sharing class LineItemDiscountHandler {

    /**
     * For each new line with a null Discount, set it to the standard discount
     * for its product. Lines that already have a Discount (including 0) are left
     * untouched.
     *
     * Bulk-safe: resolves all product families in a single query, then defers to
     * PricingRules.standardDiscountForFamily so the discount rules stay in one
     * place (PricingRules) and we never run SOQL inside the per-line loop.
     */
    public static void applyDefaultDiscounts(List<OpportunityLineItem> newLines) {
        if (newLines == null || newLines.isEmpty()) {
            return;
        }

        // In a before insert, Product2Id may not be populated yet; it is derived
        // from PricebookEntryId. Build a fallback map so we can still resolve it.
        Set<Id> pbeIds = new Set<Id>();
        for (OpportunityLineItem oli : newLines) {
            if (oli.Discount == null && oli.Product2Id == null && oli.PricebookEntryId != null) {
                pbeIds.add(oli.PricebookEntryId);
            }
        }

        Map<Id, Id> pbeToProductId = new Map<Id, Id>();
        if (!pbeIds.isEmpty()) {
            for (PricebookEntry pbe : [
                SELECT Id, Product2Id
                FROM PricebookEntry
                WHERE Id IN :pbeIds
            ]) {
                pbeToProductId.put(pbe.Id, pbe.Product2Id);
            }
        }

        // Gather the product ids we actually need to look up.
        Set<Id> productIds = new Set<Id>();
        for (OpportunityLineItem oli : newLines) {
            if (oli.Discount != null) {
                continue;
            }
            Id prodId = resolveProductId(oli, pbeToProductId);
            if (prodId != null) {
                productIds.add(prodId);
            }
        }

        if (productIds.isEmpty()) {
            return;
        }

        // One query for all families, no SOQL in the loop below.
        Map<Id, Product2> productsById = new Map<Id, Product2>([
            SELECT Id, Family
            FROM Product2
            WHERE Id IN :productIds
        ]);

        for (OpportunityLineItem oli : newLines) {
            if (oli.Discount != null) {
                continue; // rep-entered value (including 0) wins
            }
            Id prodId = resolveProductId(oli, pbeToProductId);
            if (prodId == null) {
                continue;
            }
            Product2 product = productsById.get(prodId);
            if (product == null) {
                continue;
            }
            // Rules remain owned by PricingRules.
            oli.Discount = PricingRules.standardDiscountForFamily(product.Family);
        }
    }

    private static Id resolveProductId(OpportunityLineItem oli, Map<Id, Id> pbeToProductId) {
        if (oli.Product2Id != null) {
            return oli.Product2Id;
        }
        if (oli.PricebookEntryId != null) {
            return pbeToProductId.get(oli.PricebookEntryId);
        }
        return null;
    }
}
