```javascript
import { LightningElement } from 'lwc';
import searchContacts from '@salesforce/apex/ContactController.searchContacts';

const DEBOUNCE_DELAY = 300;
const MIN_CHARS = 2;

export default class ContactSearch extends LightningElement {
    contacts = [];
    error;

    // Timer for debouncing keystrokes.
    _debounceTimeout;
    // Monotonically increasing id to track the most recent request.
    _requestId = 0;
    // Guard so no work happens after the component is removed.
    _isConnected = true;

    disconnectedCallback() {
        this._isConnected = false;
        // Cancel any pending debounced search.
        clearTimeout(this._debounceTimeout);
        // Invalidate any in-flight request so its response is ignored.
        this._requestId++;
    }

    handleChange(event) {
        const searchTerm = (event.target.value || '').trim();

        // Always cancel any previously scheduled search.
        clearTimeout(this._debounceTimeout);

        if (searchTerm.length < MIN_CHARS) {
            // Invalidate any in-flight request and clear results.
            this._requestId++;
            this.contacts = [];
            this.error = undefined;
            return;
        }

        this._debounceTimeout = setTimeout(() => {
            this.runSearch(searchTerm);
        }, DEBOUNCE_DELAY);
    }

    runSearch(searchTerm) {
        if (!this._isConnected) {
            return;
        }

        const currentRequestId = ++this._requestId;

        searchContacts({ searchTerm })
            .then((result) => {
                // Ignore if component gone or a newer request has started.
                if (!this._isConnected || currentRequestId !== this._requestId) {
                    return;
                }
                this.contacts = result;
                this.error = undefined;
            })
            .catch((error) => {
                if (!this._isConnected || currentRequestId !== this._requestId) {
                    return;
                }
                this.contacts = [];
                this.error = error;
            });
    }

    get errorMessage() {
        return this.error && this.error.body
            ? this.error.body.message
            : '';
    }
}
