import { LightningElement, api } from 'lwc';

const NAV_KEYS = ['ArrowDown', 'ArrowUp', 'Home', 'End', 'Enter', ' '];

export default class StatusListbox extends LightningElement {
    @api label;

    _options = [];
    _value = '';
    _activeValue = null;

    @api
    get options() {
        return this._options;
    }
    set options(val) {
        this._options = Array.isArray(val) ? val : [];
    }

    @api
    get value() {
        return this._value;
    }
    set value(val) {
        this._value = val === undefined || val === null ? '' : val;
        // When the parent changes the value, the active option moves to it.
        this._activeValue = this._value !== '' ? this._value : null;
    }

    // Resolve the currently active option value.
    get resolvedActiveValue() {
        if (
            this._activeValue !== null &&
            this._options.some((o) => o.value === this._activeValue)
        ) {
            return this._activeValue;
        }
        if (this._value !== '' && this._options.some((o) => o.value === this._value)) {
            return this._value;
        }
        return this._options.length ? this._options[0].value : null;
    }

    get activeDescendantId() {
        const active = this.resolvedActiveValue;
        const idx = this._options.findIndex((o) => o.value === active);
        return idx >= 0 ? `option-${idx}` : null;
    }

    get computedOptions() {
        return this._options.map((opt, i) => ({
            value: opt.value,
            label: opt.label,
            id: `option-${i}`,
            ariaSelected: opt.value === this._value ? 'true' : 'false'
        }));
    }

    handleKeydown(event) {
        const key = event.key;
        if (!NAV_KEYS.includes(key)) {
            return;
        }
        event.preventDefault();

        const options = this._options;
        if (!options.length) {
            return;
        }

        let idx = options.findIndex((o) => o.value === this.resolvedActiveValue);
        if (idx < 0) {
            idx = 0;
        }

        switch (key) {
            case 'ArrowDown':
                idx = Math.min(idx + 1, options.length - 1);
                this._activeValue = options[idx].value;
                break;
            case 'ArrowUp':
                idx = Math.max(idx - 1, 0);
                this._activeValue = options[idx].value;
                break;
            case 'Home':
                idx = 0;
                this._activeValue = options[idx].value;
                break;
            case 'End':
                idx = options.length - 1;
                this._activeValue = options[idx].value;
                break;
            case 'Enter':
            case ' ':
                this.selectValue(options[idx].value);
                break;
            default:
                break;
        }
    }

    handleClick(event) {
        const dataValue = event.currentTarget.dataset.value;
        const opt = this._options.find((o) => String(o.value) === dataValue);
        if (opt) {
            this.selectValue(opt.value);
        }
    }

    selectValue(val) {
        this._activeValue = val;
        if (val === this._value) {
            return;
        }
        this._value = val;
        this.dispatchEvent(new CustomEvent('change', { detail: { value: val } }));
    }
}
