```apex
public with sharing class EmployerService {
    /**
     * Sets each contact's current employer using NPSP's standard primary-affiliation
     * mechanism. Setting Contact.npsp__Primary_Affiliation__c causes NPSP's
     * AFFL_Affiliations_TDTM handler to:
     *   - create a Current, primary affiliation to the new organization, and
     *   - mark any previous primary affiliation as Former, non-primary with
     *     an end date of today.
     *
     * Contacts whose primary affiliation already points at the requested
     * organization are left untouched (no duplicate affiliations created).
     *
     * @param employerByContactId Map of Contact Id -> Organization Account Id.
     */
    public static void setCurrentEmployers(Map<Id, Id> employerByContactId) {
        if (employerByContactId == null || employerByContactId.isEmpty()) {
            return;
        }

        List<Contact> contactsToUpdate = new List<Contact>();

        // 1 SOQL: read the current primary affiliation so we can skip no-op changes.
        for (Contact con : [
            SELECT Id, npsp__Primary_Affiliation__c
            FROM Contact
            WHERE Id IN :employerByContactId.keySet()
        ]) {
            Id desiredOrgId = employerByContactId.get(con.Id);

            // Skip null targets and cases where nothing would change.
            if (desiredOrgId != null && con.npsp__Primary_Affiliation__c != desiredOrgId) {
                con.npsp__Primary_Affiliation__c = desiredOrgId;
                contactsToUpdate.add(con);
            }
        }

        // 1 DML: NPSP's affiliations trigger handler creates/retires affiliations
        // as part of this update, so we don't touch npe5__Affiliation__c directly.
        if (!contactsToUpdate.isEmpty()) {
            update contactsToUpdate;
        }
    }
}
