public with sharing class GauAllocationService {

    public class AllocationException extends Exception {}

    public static List<npsp__Allocation__c> allocateByPercent(Id opportunityId, Map<Id, Decimal> percentByGauId) {

        // --- Validate inputs before touching any data ---------------------

        if (opportunityId == null) {
            throw new AllocationException('An Opportunity Id is required.');
        }

        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException('At least one GAU percentage must be provided.');
        }

        Decimal total = 0;
        for (Id gauId : percentByGauId.keySet()) {
            if (gauId == null) {
                throw new AllocationException('A GAU Id in the map was null.');
            }
            Decimal pct = percentByGauId.get(gauId);
            if (pct == null || pct <= 0) {
                throw new AllocationException('Every percentage must be greater than 0.');
            }
            total += pct;
        }

        if (total > 100) {
            throw new AllocationException('The percentages add up to more than 100%.');
        }

        // Verify every referenced GAU exists and is active.
        Map<Id, npsp__General_Accounting_Unit__c> gauById = new Map<Id, npsp__General_Accounting_Unit__c>(
            [
                SELECT Id, npsp__Active__c
                FROM npsp__General_Accounting_Unit__c
                WHERE Id IN :percentByGauId.keySet()
            ]
        );

        for (Id gauId : percentByGauId.keySet()) {
            npsp__General_Accounting_Unit__c gau = gauById.get(gauId);
            if (gau == null) {
                throw new AllocationException('GAU ' + gauId + ' was not found.');
            }
            if (gau.npsp__Active__c != true) {
                throw new AllocationException('GAU ' + gauId + ' is inactive.');
            }
        }

        // --- All validation passed: now mutate data -----------------------

        // Remove any existing allocations for this opportunity.
        List<npsp__Allocation__c> existing = [
            SELECT Id
            FROM npsp__Allocation__c
            WHERE npsp__Opportunity__c = :opportunityId
        ];
        if (!existing.isEmpty()) {
            delete existing;
        }

        // Build one percent-based allocation per entry. Setting
        // npsp__Percent__c (and leaving npsp__Amount__c null) lets NPSP keep
        // the dollar amounts in sync automatically when the Opportunity amount
        // changes later.
        List<npsp__Allocation__c> toInsert = new List<npsp__Allocation__c>();
        for (Id gauId : percentByGauId.keySet()) {
            toInsert.add(new npsp__Allocation__c(
                npsp__Opportunity__c = opportunityId,
                npsp__General_Accounting_Unit__c = gauId,
                npsp__Percent__c = percentByGauId.get(gauId)
            ));
        }

        insert toInsert;

        return toInsert;
    }
}
