public with sharing class HouseholdService {
    /**
     * Registers a whole family at once into a single NPSP Household Account.
     *
     * The contacts are expected to be new (no Id, no AccountId). They are all
     * placed into ONE newly created NPSP household, with the first contact in
     * the list as the household's primary contact.
     *
     * @param members the family members to register (first one becomes primary)
     * @return the Id of the newly created Household Account
     */
    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('members must not be null or empty');
        }

        // Insert the primary (first) contact on its own. In the NPSP Household
        // Account model this makes NPSP automatically create exactly one
        // Household Account (Household Account record type), name it and
        // generate the household greetings for us. We never set the Account
        // name or record type ourselves, so NPSP stays in full control.
        Contact primary = members[0];
        insert primary;

        // NPSP reparents the contact to the freshly created household inside an
        // after-insert trigger, so the in-memory AccountId is not populated.
        // Re-query to obtain the household Account Id.
        Id householdId = [
            SELECT AccountId
            FROM Contact
            WHERE Id = :primary.Id
            LIMIT 1
        ].AccountId;

        // Add the remaining family members to the SAME household. Because they
        // already carry an AccountId, NPSP will not spin up extra/empty
        // households for them.
        if (members.size() > 1) {
            List<Contact> others = new List<Contact>();
            for (Integer i = 1; i < members.size(); i++) {
                members[i].AccountId = householdId;
                others.add(members[i]);
            }
            insert others;
        }

        // Ensure the first contact is recorded as the household's primary
        // contact (NPSP stores this in npe01__One2OneContact__c), which drives
        // the primary contact lookup and greeting calculations.
        update new Account(
            Id = householdId,
            npe01__One2OneContact__c = primary.Id
        );

        return householdId;
    }
}
