public with sharing class SoftCreditService {

    public class SoftCreditException extends Exception {}

    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        // Null or empty input does nothing.
        if (requests == null || requests.isEmpty()) {
            return;
        }

        // Collect the ids we need to work with.
        Set<Id> oppIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();
        for (SoftCreditRequest r : requests) {
            oppIds.add(r.opportunityId);
            contactIds.add(r.contactId);
        }

        // SOQL 1: opportunities (for amount + primary contact).
        Map<Id, Opportunity> oppMap = new Map<Id, Opportunity>([
            SELECT Id, Amount, npsp__Primary_Contact__c
            FROM Opportunity
            WHERE Id IN :oppIds
        ]);

        // Validate the whole call before any DML.
        for (SoftCreditRequest r : requests) {
            Opportunity opp = oppMap.get(r.opportunityId);
            if (opp == null) {
                throw new SoftCreditException(
                    'Opportunity ' + r.opportunityId + ' was not found.'
                );
            }
            if (r.contactId != null && r.contactId == opp.npsp__Primary_Contact__c) {
                throw new SoftCreditException(
                    'Contact ' + r.contactId +
                    ' is the primary contact of opportunity ' + r.opportunityId +
                    ' and cannot receive a soft credit.'
                );
            }
            if (r.amount == null || r.amount <= 0) {
                throw new SoftCreditException(
                    'Soft credit amount must be a positive value for opportunity ' +
                    r.opportunityId + '.'
                );
            }
            if (opp.Amount != null && r.amount > opp.Amount) {
                throw new SoftCreditException(
                    'Soft credit amount (' + r.amount +
                    ') cannot exceed the opportunity amount (' + opp.Amount +
                    ') for opportunity ' + r.opportunityId + '.'
                );
            }
        }

        // SOQL 2: existing contact roles for the requested opp/contact pairs.
        Map<String, List<OpportunityContactRole>> ocrByPair =
            new Map<String, List<OpportunityContactRole>>();
        for (OpportunityContactRole ocr : [
            SELECT Id, OpportunityId, ContactId, Role
            FROM OpportunityContactRole
            WHERE OpportunityId IN :oppIds
            AND ContactId IN :contactIds
        ]) {
            String key = pairKey(ocr.OpportunityId, ocr.ContactId);
            if (!ocrByPair.containsKey(key)) {
                ocrByPair.put(key, new List<OpportunityContactRole>());
            }
            ocrByPair.get(key).add(ocr);
        }

        // SOQL 3: existing partial soft credits for the requested pairs.
        Map<String, npsp__Partial_Soft_Credit__c> pscByPair =
            new Map<String, npsp__Partial_Soft_Credit__c>();
        for (npsp__Partial_Soft_Credit__c psc : [
            SELECT Id, npsp__Opportunity__c, npsp__Contact__c,
                   npsp__Amount__c, npsp__Role_Name__c, npsp__Contact_Role_ID__c
            FROM npsp__Partial_Soft_Credit__c
            WHERE npsp__Opportunity__c IN :oppIds
            AND npsp__Contact__c IN :contactIds
        ]) {
            String key = pairKey(psc.npsp__Opportunity__c, psc.npsp__Contact__c);
            pscByPair.put(key, psc);
        }

        // Resolve, per request, the single contact role we will keep/use.
        Map<String, OpportunityContactRole> chosenOcrByPair =
            new Map<String, OpportunityContactRole>();
        List<OpportunityContactRole> ocrsToUpsert = new List<OpportunityContactRole>();
        List<OpportunityContactRole> ocrsToDelete = new List<OpportunityContactRole>();

        for (SoftCreditRequest r : requests) {
            String key = pairKey(r.opportunityId, r.contactId);
            List<OpportunityContactRole> existing = ocrByPair.get(key);

            OpportunityContactRole chosen;
            if (existing == null || existing.isEmpty()) {
                // No contact role yet -> create exactly one with the requested role.
                chosen = new OpportunityContactRole(
                    OpportunityId = r.opportunityId,
                    ContactId = r.contactId,
                    Role = r.role
                );
            } else {
                // Reuse the first existing role, delete any extras so exactly one remains.
                chosen = existing[0];
                chosen.Role = r.role;
                for (Integer i = 1; i < existing.size(); i++) {
                    ocrsToDelete.add(existing[i]);
                }
            }
            chosenOcrByPair.put(key, chosen);
            ocrsToUpsert.add(chosen);
        }

        // DML 1: remove any duplicate contact roles.
        if (!ocrsToDelete.isEmpty()) {
            delete ocrsToDelete;
        }

        // DML 2: insert/update the single kept contact role per pair.
        upsert ocrsToUpsert;

        // Build the partial soft credits, now that contact role ids exist.
        List<npsp__Partial_Soft_Credit__c> pscsToUpsert =
            new List<npsp__Partial_Soft_Credit__c>();

        for (SoftCreditRequest r : requests) {
            String key = pairKey(r.opportunityId, r.contactId);
            OpportunityContactRole ocr = chosenOcrByPair.get(key);

            npsp__Partial_Soft_Credit__c psc = pscByPair.get(key);
            if (psc == null) {
                psc = new npsp__Partial_Soft_Credit__c(
                    npsp__Opportunity__c = r.opportunityId,
                    npsp__Contact__c = r.contactId
                );
            }
            psc.npsp__Amount__c = r.amount;
            psc.npsp__Role_Name__c = r.role;
            psc.npsp__Contact_Role_ID__c = String.valueOf(ocr.Id);
            pscsToUpsert.add(psc);
        }

        // DML 3: insert/update the partial soft credits.
        upsert pscsToUpsert;
    }

    private static String pairKey(Id opportunityId, Id contactId) {
        return String.valueOf(opportunityId) + '|' + String.valueOf(contactId);
    }
}
