/**
 * Records a gift (donation) that has already been received, crediting it the
 * way NPSP (Household Account model + NPSP Payments) expects.
 *
 * NPSP automation will fire when the Opportunity is inserted (it may create a
 * primary Opportunity Contact Role and an auto Payment). This service therefore
 * *reconciles* the resulting state rather than blindly inserting, guaranteeing:
 *   - exactly one contact role per contact (Donor for the primary, Household
 *     Member for every other household member),
 *   - exactly one Payment (paid, full amount, dated on the gift date).
 */
public with sharing class GiftService {

    private static final String DONOR_ROLE = 'Donor';
    private static final String HOUSEHOLD_MEMBER_ROLE = 'Household Member';
    private static final String CLOSED_WON = 'Closed Won';

    public static Id recordGift(Id contactId, Decimal amount, Date giftDate) {

        // ---- Validate inputs ------------------------------------------------
        if (amount == null || amount <= 0) {
            throw new IllegalArgumentException(
                'Gift amount must be a positive, non-zero value.'
            );
        }
        if (giftDate == null) {
            throw new IllegalArgumentException('Gift date is required.');
        }

        List<Contact> contacts = [
            SELECT Id, FirstName, LastName, AccountId
            FROM Contact
            WHERE Id = :contactId
            LIMIT 1
        ];
        if (contacts.isEmpty()) {
            throw new IllegalArgumentException(
                'Contact does not exist: ' + contactId
            );
        }

        Contact donor = contacts[0];
        if (donor.AccountId == null) {
            throw new IllegalArgumentException(
                'Contact has no household account: ' + contactId
            );
        }

        // ---- Create the gift (Opportunity) ---------------------------------
        Opportunity opp = new Opportunity(
            Name                       = buildOppName(donor, giftDate),
            AccountId                  = donor.AccountId,
            npsp__Primary_Contact__c   = donor.Id,
            Amount                     = amount,
            CloseDate                  = giftDate,
            StageName                  = CLOSED_WON
        );
        insert opp;

        // NPSP triggers have now run; reconcile roles and payments.
        reconcileContactRoles(opp.Id, donor);
        reconcilePayments(opp.Id, amount, giftDate);

        return opp.Id;
    }

    // ------------------------------------------------------------------------
    //  Contact Roles
    // ------------------------------------------------------------------------
    private static void reconcileContactRoles(Id opportunityId, Contact donor) {

        // All members of the donor's household.
        List<Contact> householdMembers = [
            SELECT Id
            FROM Contact
            WHERE AccountId = :donor.AccountId
        ];

        // Existing roles (possibly created by NPSP automation).
        List<OpportunityContactRole> existing = [
            SELECT Id, ContactId, Role, IsPrimary
            FROM OpportunityContactRole
            WHERE OpportunityId = :opportunityId
        ];

        // Keep at most one role per contact; mark the rest for deletion.
        Map<Id, OpportunityContactRole> keepByContact =
            new Map<Id, OpportunityContactRole>();
        List<OpportunityContactRole> rolesToDelete =
            new List<OpportunityContactRole>();

        for (OpportunityContactRole r : existing) {
            if (keepByContact.containsKey(r.ContactId)) {
                rolesToDelete.add(r);
            } else {
                keepByContact.put(r.ContactId, r);
            }
        }

        List<OpportunityContactRole> rolesToUpsert =
            new List<OpportunityContactRole>();

        // Primary / donor role.
        OpportunityContactRole donorRole = keepByContact.get(donor.Id);
        if (donorRole == null) {
            donorRole = new OpportunityContactRole(
                OpportunityId = opportunityId,
                ContactId     = donor.Id
            );
        }
        donorRole.Role      = DONOR_ROLE;
        donorRole.IsPrimary = true;
        rolesToUpsert.add(donorRole);

        // Every other household member gets the Household Member role.
        for (Contact member : householdMembers) {
            if (member.Id == donor.Id) {
                continue;
            }
            OpportunityContactRole memberRole = keepByContact.get(member.Id);
            if (memberRole == null) {
                memberRole = new OpportunityContactRole(
                    OpportunityId = opportunityId,
                    ContactId     = member.Id
                );
            }
            memberRole.Role      = HOUSEHOLD_MEMBER_ROLE;
            memberRole.IsPrimary = false;
            rolesToUpsert.add(memberRole);
        }

        if (!rolesToDelete.isEmpty()) {
            delete rolesToDelete;
        }
        if (!rolesToUpsert.isEmpty()) {
            upsert rolesToUpsert;
        }
    }

    // ------------------------------------------------------------------------
    //  Payments
    // ------------------------------------------------------------------------
    private static void reconcilePayments(
        Id opportunityId,
        Decimal amount,
        Date giftDate
    ) {
        List<npe01__OppPayment__c> payments = [
            SELECT Id
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :opportunityId
            ORDER BY CreatedDate ASC
        ];

        npe01__OppPayment__c payment;
        List<npe01__OppPayment__c> paymentsToDelete =
            new List<npe01__OppPayment__c>();

        if (payments.isEmpty()) {
            payment = new npe01__OppPayment__c(
                npe01__Opportunity__c = opportunityId
            );
        } else {
            // Keep the first payment, remove any duplicates.
            payment = payments[0];
            for (Integer i = 1; i < payments.size(); i++) {
                paymentsToDelete.add(payments[i]);
            }
        }

        payment.npe01__Payment_Amount__c = amount;
        payment.npe01__Payment_Date__c   = giftDate;
        payment.npe01__Scheduled_Date__c = giftDate;
        payment.npe01__Paid__c           = true;

        if (!paymentsToDelete.isEmpty()) {
            delete paymentsToDelete;
        }
        upsert payment;
    }

    // ------------------------------------------------------------------------
    //  Helpers
    // ------------------------------------------------------------------------
    private static String buildOppName(Contact donor, Date giftDate) {
        String firstName = String.isBlank(donor.FirstName)
            ? '' : donor.FirstName.trim();
        String lastName = String.isBlank(donor.LastName)
            ? '' : donor.LastName.trim();
        String personName = (firstName + ' ' + lastName).trim();
        return (personName + ' Donation ' + formatDate(giftDate)).trim();
    }

    private static String formatDate(Date d) {
        return String.valueOf(d.year())
            + '-' + pad(d.month())
            + '-' + pad(d.day());
    }

    private static String pad(Integer value) {
        return value < 10 ? '0' + value : String.valueOf(value);
    }
}
