```apex
/**
 * Returns the subset of record IDs that the running user can edit, as reported
 * by the UserRecordAccess object (HasEditAccess). This honours object
 * permissions, ownership, sharing rules, the role hierarchy and
 * View All / Modify All, because UserRecordAccess reflects all of them.
 */
public with sharing class RecordAccessService {

    // UserRecordAccess only allows up to 200 record IDs in the RecordId filter
    // per query, so we chunk the input. 2,000 IDs => 10 queries (<= 20 limit).
    private static final Integer MAX_IDS_PER_QUERY = 200;

    public static Set<Id> editableIds(Set<Id> recordIds) {
        Set<Id> editable = new Set<Id>();

        if (recordIds == null || recordIds.isEmpty()) {
            return editable;
        }

        Id userId = UserInfo.getUserId();

        // Work from a List so we can slice into fixed-size chunks.
        List<Id> allIds = new List<Id>(recordIds);
        Integer total = allIds.size();

        for (Integer start = 0; start < total; start += MAX_IDS_PER_QUERY) {
            Integer stop = Math.min(start + MAX_IDS_PER_QUERY, total);

            Set<Id> chunk = new Set<Id>();
            for (Integer i = start; i < stop; i++) {
                chunk.add(allIds[i]);
            }

            for (UserRecordAccess access : [
                SELECT RecordId
                FROM UserRecordAccess
                WHERE UserId = :userId
                  AND RecordId IN :chunk
                  AND HasEditAccess = true
            ]) {
                editable.add(access.RecordId);
            }
        }

        return editable;
    }
}
```

