/**
 * Service for reassigning ownership of Accounts and their Contacts.
 *
 * The Account trigger actions are expensive (territory recalculation) and must not run
 * for an ownership change, so the whole Account sObject is bypassed via the Trigger
 * Actions Framework for the duration of the Account DML. Contact trigger actions run
 * normally. The bypass is always cleared in a finally block so Account automation
 * behaves normally for the rest of the transaction, whether or not the operation
 * succeeds.
 */
public with sharing class AccountOwnershipService {
    public static void reassign(Set<Id> accountIds, Id newOwnerId) {
        if (accountIds == null || accountIds.isEmpty() || newOwnerId == null) {
            return;
        }

        // Build Account records to update without a query (we already have the Ids).
        List<Account> accountsToUpdate = new List<Account>();
        for (Id accountId : accountIds) {
            accountsToUpdate.add(new Account(Id = accountId, OwnerId = newOwnerId));
        }

        // Query the Contacts belonging to the given Accounts (SOQL #1).
        List<Contact> contactsToUpdate = [
            SELECT Id
            FROM Contact
            WHERE AccountId IN :accountIds
        ];
        for (Contact con : contactsToUpdate) {
            con.OwnerId = newOwnerId;
        }

        try {
            // Suppress all Account trigger actions for this transaction.
            TriggerBase.bypass('Account');

            // DML #1: Account update runs with Account automation bypassed.
            update accountsToUpdate;

            // DML #2: Contact update runs with Contact automation active.
            if (!contactsToUpdate.isEmpty()) {
                update contactsToUpdate;
            }
        } finally {
            // Always restore normal Account automation for the rest of the transaction.
            TriggerBase.clearBypass('Account');
        }
    }
}
