/**
 * Trigger action (TAF) that normalizes contact info on Leads during before insert.
 * Runs in the before-insert context so the cleaned values are persisted on first save,
 * requiring no extra DML and no SOQL. Bulk-safe for 200 records in one insert.
 */
public inherited sharing class TA_Lead_NormalizeContactInfo implements TriggerAction.BeforeInsert {
    public void beforeInsert(List<SObject> triggerNew) {
        for (Lead lead : (List<Lead>) triggerNew) {
            // Email: trim and lower-case; null stays null.
            if (lead.Email != null) {
                lead.Email = lead.Email.trim().toLowerCase();
            }

            // Company: trim leading/trailing whitespace.
            if (lead.Company != null) {
                lead.Company = lead.Company.trim();
            }

            // LeadSource: default to 'Web' when blank; keep existing values.
            if (String.isBlank(lead.LeadSource)) {
                lead.LeadSource = 'Web';
            }
        }
    }
}
